}

void CreateResultObject(const napi_env& env, AsyncContext* context)
{
    if (context == nullptr || env == nullptr) {
        LBSLOGE(LOCATOR_STANDARD, "CreateResultObject input para error");
        return;
    }
    if (context->errCode != SUCCESS) {
        std::string errMsg = CommonUtils::GetErrorMsgByCode(context->errCode);
        context->errCode = CommonUtils::ConvertErrorCode(context->errCode);
        context->result[PARAM0] = GetErrorObject(env, context->errCode, errMsg);
        NAPI_CALL_RETURN_VOID(env, napi_get_undefined(env, &context->result[PARAM1]));
    } else {
        NAPI_CALL_RETURN_VOID(env, napi_get_undefined(env, &context->result[PARAM0]));
    }
}

void SendResultToJs(const napi_env& env, AsyncContext* context)
{
    if (context == nullptr || env == nullptr) {
        LBSLOGE(LOCATOR_STANDARD, "SendResultToJs input para error");
        return;
    }

    bool isPromise = context->deferred != nullptr;
    if (isPromise) {
        if (context->errCode != SUCCESS) {
            napi_status status = napi_reject_deferred(env, context->deferred, context->result[PARAM0]);
            if (status != napi_ok) {
                LBSLOGE(LOCATOR_STANDARD, "SendResultToJs napi_reject_deferred fail status: %{public}d", status);
            }
        } else {
            napi_status status = napi_resolve_deferred(env, context->deferred, context->result[PARAM1]);
            if (status != napi_ok) {
                LBSLOGE(LOCATOR_STANDARD, "SendResultToJs napi_reject_deferred fail status: %{public}d", status);
            }
        }
    } else {
        napi_value undefine;
        napi_get_undefined(env, &undefine);
        napi_value callback;
        napi_status getCallbackStatus = napi_get_reference_value(env, context->callback[0], &callback);
        if (getCallbackStatus != napi_ok) {
            LBSLOGE(LOCATOR_STANDARD, "SendResultToJs getCallbackStatus fail status: %{public}d", getCallbackStatus);
            return;
        }
        napi_status callFunStatus = napi_call_function(env, nullptr, callback, RESULT_SIZE, context->result, &undefine);
        if (callFunStatus != napi_ok) {
            LBSLOGE(LOCATOR_STANDARD, "SendResultToJs getCallFun fail status: %{public}d", callFunStatus);
        }
    }
}

void MemoryReclamation(const napi_env& env, AsyncContext* context)
{
    if (context == nullptr || env == nullptr) {
        LBSLOGE(LOCATOR_STANDARD, "MemoryReclamation input para error");
        return;
    }

    if (context->callback[SUCCESS_CALLBACK] != nullptr) {
        napi_status status = napi_delete_reference(env, context->callback[SUCCESS_CALLBACK]);
        LBSLOGE(LOCATOR_STANDARD, "napi_delete_reference for success callback status: %{public}d", status);
    }
    if (context->callback[FAIL_CALLBACK] != nullptr) {
        napi_status status = napi_delete_reference(env, context->callback[FAIL_CALLBACK]);
        LBSLOGE(LOCATOR_STANDARD, "napi_delete_reference for fail callback status: %{public}d", status);
    }
    if (context->callback[COMPLETE_CALLBACK] != nullptr) {
        napi_status status = napi_delete_reference(env, context->callback[COMPLETE_CALLBACK]);
        LBSLOGE(LOCATOR_STANDARD, "napi_delete_reference for fail complete status: %{public}d", status);
    }
    napi_status deleteWorkStatus = napi_delete_async_work(env, context->work);
    if (deleteWorkStatus != napi_ok) {
        LBSLOGE(LOCATOR_STANDARD, "napi_delete_async_work fail status: %{public}d", deleteWorkStatus);
    }
    delete context;
    context = nullptr;
}

static napi_value CreateAsyncWork(const napi_env& env, AsyncContext* asyncContext)
{
    if (asyncContext == nullptr) {
        return UndefinedNapiValue(env);
    }
    napi_status createWorkStatus = napi_create_async_work(
        env, nullptr, asyncContext->resourceName,
        [](napi_env env, void* data) {
            if (data == nullptr) {
                LBSLOGE(LOCATOR_STANDARD, "Async data parameter is null");
                return;
            }
            AsyncContext* context = static_cast<AsyncContext *>(data);
            context->executeFunc(context);
        },
        [](napi_env env, napi_status status, void* data) {
            if (data == nullptr) {
                LBSLOGE(LOCATOR_STANDARD, "Async data parameter is null");
                return;
            }
            AsyncContext* context = static_cast<AsyncContext *>(data);
            context->completeFunc(data);
            CreateResultObject(env, context);
            SendResultToJs(env, context);
            MemoryReclamation(env, context);
        }, static_cast<void*>(asyncContext), &asyncContext->work);
    if (createWorkStatus != napi_ok) {
        LBSLOGE(LOCATOR_STANDARD, "napi_create_async_work fail status: %{public}d", createWorkStatus);
        asyncContext->isAsyncWorkAddToQueue = false;
        MemoryReclamation(env, asyncContext);
        return UndefinedNapiValue(env);
    }
    napi_status queueWorkStatus = napi_queue_async_work(env, asyncContext->work);
    if (queueWorkStatus != napi_ok) {
        LBSLOGE(LOCATOR_STANDARD, "napi_queue_async_work fail status: %{public}d", queueWorkStatus);
        asyncContext->isAsyncWorkAddToQueue = false;
        MemoryReclamation(env, asyncContext);
        return UndefinedNapiValue(env);
    }
    asyncContext->isAsyncWorkAddToQueue = true;
    return UndefinedNapiValue(env);
}

napi_value DoAsyncWork(const napi_env& env, AsyncContext* asyncContext,
    const size_t argc, const napi_value* argv, const size_t objectArgsNum)
{
    if (asyncContext == nullptr || argv == nullptr) {
        return UndefinedNapiValue(env);
    }
    if (argc > objectArgsNum) {
        InitAsyncCallBackEnv(env, asyncContext, argc, argv, objectArgsNum);
        return CreateAsyncWork(env, asyncContext);
    } else {
        napi_value promise;
        InitAsyncPromiseEnv(env, asyncContext, promise);
        CreateAsyncWork(env, asyncContext);
        return promise;
    }
}

void DeleteQueueWork(AsyncContext* context)
{
    uv_loop_s *loop = nullptr;
    if (context->env == nullptr) {
        LBSLOGE(LOCATOR_STANDARD, "env is nullptr.");
        delete context;
        return;
    }
    NAPI_CALL_RETURN_VOID(context->env, napi_get_uv_event_loop(context->env, &loop));
    if (loop == nullptr) {
        LBSLOGE(LOCATOR_STANDARD, "loop == nullptr.");
        delete context;
        return;
    }
    uv_work_t *work = new (std::nothrow) uv_work_t;
    if (work == nullptr) {
        LBSLOGE(LOCATOR_STANDARD, "work == nullptr.");
        delete context;
        return;
    }
    work->data = context;
    DeleteCallbackHandler(loop, work);
}

void DeleteCallbackHandler(uv_loop_s *&loop, uv_work_t *&work)
{
    uv_queue_work_internal(loop, work, [](uv_work_t *work) {},
        [](uv_work_t *work, int status) {
            AsyncContext *context = nullptr;
            napi_handle_scope scope = nullptr;
            if (work == nullptr) {
                LBSLOGE(LOCATOR_CALLBACK, "work is nullptr");
                return;
            }
            context = static_cast<AsyncContext *>(work->data);
            if (context == nullptr || context->env == nullptr) {
                LBSLOGE(LOCATOR_CALLBACK, "context is nullptr");
                delete work;
                return;
            }
            NAPI_CALL_RETURN_VOID(context->env, napi_open_handle_scope(context->env, &scope));
            if (scope == nullptr) {
                LBSLOGE(LOCATOR_CALLBACK, "scope is nullptr");
                delete context;
                delete work;
                return;
            }
            if (context->callback[SUCCESS_CALLBACK] != nullptr) {
                CHK_NAPI_ERR_CLOSE_SCOPE(context->env,
                    napi_delete_reference(context->env, context->callback[SUCCESS_CALLBACK]),
                    scope, context, work);
            }
            if (context->callback[FAIL_CALLBACK] != nullptr) {
                CHK_NAPI_ERR_CLOSE_SCOPE(context->env,
                    napi_delete_reference(context->env, context->callback[FAIL_CALLBACK]),
                    scope, context, work);
            }
            if (context->callback[COMPLETE_CALLBACK] != nullptr) {
                CHK_NAPI_ERR_CLOSE_SCOPE(context->env,
                    napi_delete_reference(context->env, context->callback[COMPLETE_CALLBACK]),
                    scope, context, work);
            }
            NAPI_CALL_RETURN_VOID(context->env, napi_close_handle_scope(context->env, scope));
            delete context;
            delete work;
    }, "deleteCallback");
}

