LocationErrCode GnssAbility::RegisterCachedCallback(const std::unique_ptr<CachedGnssLocationsRequest>& request,
    const sptr<IRemoteObject>& callback)
{
    if (callback == nullptr) {
        LBSLOGE(GNSS, "register an invalid cached location callback");
        return LOCATION_ERRCODE_INVALID_PARAM;
    }
    if (!IsSupportGps()) {
        LBSLOGI(GNSS, "Is Not Support Gps");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    if (!IsSupportBatching()) {
        LBSLOGE(GNSS, "Is Not Support Batching");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    {
        std::unique_lock<ffrt::mutex> lock(batchingMutex_);
        if (batchingCallbackMap_.size() < MAX_CACHE_CALLBACK_NUM) {
            sptr<IRemoteObject::DeathRecipient> death(new (std::nothrow) CachedLocationCallbackDeathRecipient());
            callback->AddDeathRecipient(death);
            batchingDeathMap_[callback] = death;
            batchingCallbackMap_[callback] = std::make_unique<CachedGnssLocationsRequest>(*request);
        } else {
            LBSLOGE(GNSS, "RegisterGnssStatusCallback num max");
            return ERRCODE_SERVICE_UNAVAILABLE;
        }
    }
    StopGnssBatching();
    StopGnss();
    int64_t batchIntervalMs = std::max(GetReportingPeriodSecParam(), MIN_BATCH_LENGTH_MS);
    StartGnssBatching(batchIntervalMs, GetWakeUpCacheQueueFullParam());
    LBSLOGD(GNSS, "request:%{public}d ,%{public}d",
        request->reportingPeriodSec, request->wakeUpCacheQueueFull ? 1 : 0);
    return ERRCODE_SUCCESS;
}

LocationErrCode GnssAbility::UnregisterCachedCallback(const sptr<IRemoteObject>& callback)
{
    if (callback == nullptr) {
        LBSLOGE(GNSS, "register an invalid cached location callback");
        return LOCATION_ERRCODE_INVALID_PARAM;
    }
    if (!IsSupportGps()) {
        LBSLOGI(GNSS, "Is Not Support Gps");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    if (!IsSupportBatching()) {
        LBSLOGE(GNSS, "Is Not Support Batching");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    {
        std::unique_lock<ffrt::mutex> lock(batchingMutex_);
        auto deathIter = batchingDeathMap_.find(callback);
        if (deathIter != batchingDeathMap_.end()) {
            callback->RemoveDeathRecipient(deathIter->second);
            batchingDeathMap_.erase(deathIter);
        }
        auto iter = batchingCallbackMap_.find(callback);
        if (iter != batchingCallbackMap_.end()) {
            batchingCallbackMap_.erase(iter);
        }
    }
    if (GetBatchingRequestNum() == 0) {
        StopGnssBatching();
    }
    return ERRCODE_SUCCESS;
}

void GnssAbility::RequestRecord(WorkRecord &workRecord, bool isAdded)
{
    LBSLOGD(GNSS, "enter RequestRecord");
    if (!IsSupportGps()) {
        LBSLOGI(GNSS, "Is Not Support Gps");
        return;
    }
    if (isAdded) {
        int gnssEnableState  = LocationConfigManager::GetInstance()->GetGnssEnableState();
        uint32_t tokenId = workRecord.GetTokenId(0);
        uint32_t firstTokenId = workRecord.GetFirstTokenId(0);
        bool ignoredSwitchPermission = PermissionManager::CheckLocationSwitchIgnoredPermission(tokenId, firstTokenId);
        if (!gnssEnableState && !ignoredSwitchPermission) {
            LBSLOGE(GNSS, "gnss enablestate false!");
            return;
        }
        if (!CheckIfHdiConnected()) {
            auto startTime = CommonUtils::GetCurrentTimeStamp();
            auto ret = false;
#ifndef TDD_CASES_ENABLED
            ret = ConnectHdi();
#endif
            auto endTime = CommonUtils::GetCurrentTimeStamp();
            WriteLocationInnerEvent(HDI_EVENT, {"ret", std::to_string(ret), "type", "ConnectHdi",
                    "startTime", std::to_string(startTime), "endTime", std::to_string(endTime)});
        }
        EnableGnss();
#ifdef HDF_DRIVERS_INTERFACE_AGNSS_ENABLE
        SetAgnssServer();
#endif
        StartGnss();
        LocatorRequestStruct locatorRequestStruct;
        locatorRequestStruct.bundleName = workRecord.GetName(0);
        LocationErrCode errorCode = HookUtils::ExecuteHook(LocationProcessStage::GNSS_REQUEST_RECORD_PROCESS,
            (void *)&locatorRequestStruct, nullptr);
    } else {
        // GNSS will stop only if all requests have stopped
        if (GetRequestNum() == 0) {
            StopGnss();
        }
        // GNSS will disable if all requests have stopped and location switch is off
        if (GetRequestNum() == 0 && LocationDataRdbManager::QuerySystemSwitchState() != ENABLED) {
            DisableGnss();
        }
    }
    std::string state = isAdded ? "start" : "stop";
    WriteGnssStateEvent(state, workRecord.GetPid(0), workRecord.GetUid(0));
}

