void GnssAbility::RestoreGeofenceRequest()
{
#ifdef HDF_DRIVERS_INTERFACE_GEOFENCE_ENABLE
    // 读取固化数据
    std::vector<std::shared_ptr<GeofenceRequest>> requestList = ReadGeoFenceRequestFromFile();
    int32_t fenceId = 0;
    for (auto iter : requestList) {
        // 是否超期，超期不恢复
        if (CommonUtils::GetCurrentTimeMilSec() > iter->GetRequestExpirationTimeStamp()) {
            LBSLOGI(GNSS, "geofence request is expiration, not need restore, %{public}s, %{public}d",
                iter->GetBundleName().c_str(), iter->GetFenceId());
            continue;
        }
        bool hasNotification = false;
#ifdef NOTIFICATION_ENABLE
        auto notificationRequestList = iter->GetNotificationRequestList();
        if (notificationRequestList.size() != 0) {
            hasNotification = true;
        }
#endif
        if (!hasNotification && iter->GetWantAgent() == nullptr &&
            iter->GetFenceExtensionAbilityName().empty()) {
            LBSLOGI(GNSS, "have not callback type, not need restore, %{public}s, %{public}d",
                iter->GetBundleName().c_str(), iter->GetFenceId());
            continue;
        }
        // 满足恢复条件
        if (iter->GetWantAgent() == nullptr) {
            {
                std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
                gnssGeofenceRequestList_.push_back(iter);
                gnssGeofenceRequestCountMap_[iter->GetBundleName()]++;
            }
            AddGnssGeofence(iter);
        } else {
            AddFence(iter);
        }
        if (iter->GetFenceId() > fenceId) {
            fenceId = iter->GetFenceId();
        }
    }
    if (fenceId > 0) {
        // 初始化fenceId
        InitGeofenceId(fenceId);
    }
    LBSLOGI(GNSS, "After RestoreGeofenceRequest size %{public}zu", gnssGeofenceRequestList_.size());
#endif
}

LocationErrCode GnssAbility::InjectTime()
{
#ifdef TIME_SERVICE_ENABLE
    LBSLOGD(GNSS, "InjectTime");
    int64_t currentTime = ntpTime_.GetCurrentTime();
    if (currentTime == INVALID_TIME) {
        return ERRCODE_SERVICE_UNAVAILABLE;
    }
    auto elapsedTime = MiscServices::TimeServiceClient::GetInstance()->GetBootTimeMs();
    if (elapsedTime < 0) {
        LBSLOGE(GNSS, "get boot time failed");
        return ERRCODE_SERVICE_UNAVAILABLE;
    }
    auto ntpTimeCheck = NtpTimeCheck::GetInstance();
    if (ntpTimeCheck != nullptr && ntpTimeCheck->CheckNtpTime(currentTime, elapsedTime)) {
        GnssRefInfo refInfo;
        refInfo.type = GnssRefInfoType::GNSS_REF_INFO_TIME;
        refInfo.time.time = currentTime;
        refInfo.time.elapsedRealtime = elapsedTime;
        refInfo.time.uncertaintyOfTime = ntpTimeCheck->GetUncertainty();
        auto gnssInterface = IGnssInterface::Get();
        if (gnssInterface != nullptr) {
            LBSLOGI(GNSS, "inject ntp time: %{public}s unert %{public}d",
                std::to_string(currentTime).c_str(), ntpTimeCheck->GetUncertainty());
            gnssInterface->SetGnssReferenceInfo(refInfo);
        }
    }
#endif
    return ERRCODE_SUCCESS;
}

LocationErrCode GnssAbility::UpdateNtpTime(int64_t ntpTime, int64_t elapsedTime)
{
#ifdef TIME_SERVICE_ENABLE
    if (ntpTime <= 0 || elapsedTime <= 0) {
        LBSLOGE(GNSS, "failed to UpdateNtpTime");
        return ERRCODE_SERVICE_UNAVAILABLE;
    }
    ntpTime_.SetCurrentTime(ntpTime, elapsedTime);
#endif
    return ERRCODE_SUCCESS;
}

