}

LocationErrCode GnssAbility::AddFence(std::shared_ptr<GeofenceRequest>& request)
{
    if (!IsSupportGeofence()) {
        LBSLOGI(GNSS, "Is Not Support Geofence");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    if ((GetGnssGeofenceRequestMapSize()) >= MAX_GNSS_GEOFENCE_REQUEST_NUM) {
        LBSLOGE(GNSS, "Exceeded the limit of the fence request");
        return ERRCODE_GEOFENCE_EXCEED_MAXIMUM;
    }
    if (CheckIfExceedsLimitForOneApp(request->GetBundleName())) {
        LBSLOGE(GNSS, "Exceeded the limit of the fence request for one app");
        DeleteMinExpirationGeofenceRequest(request->GetBundleName());
    }
    if (IsDuplicateOnRequestForGnssGeofence(request)) {
        LBSLOGE(GNSS, "has same request, return");
        return ERRCODE_GEOFENCE_FAIL;
    }
    int fenceId = 0;
    if (request->GetFenceId() > 0) {
        fenceId = request->GetFenceId();
    } else {
        fenceId = GenerateFenceId();
        request->SetFenceId(fenceId);
    }
#ifdef HDF_DRIVERS_INTERFACE_GEOFENCE_ENABLE
    sptr<IGeofenceInterface> geofenceInterface = IGeofenceInterface::Get();
    if (geofenceInterface == nullptr) {
        LBSLOGE(GNSS, "geofenceInterface is nullptr");
        return ERRCODE_SERVICE_UNAVAILABLE;
    }
    auto geofence = request->GetGeofence();
    request->SetRequestExpirationTimeStamp(CommonUtils::GetCurrentTimeMilSec() + geofence.expiration);
    GeofenceInfo fenceInfo;
    fenceInfo.fenceIndex = fenceId;
    fenceInfo.latitude = geofence.latitude;
    fenceInfo.longitude = geofence.longitude;
    fenceInfo.radius = geofence.radius;
    int monitorEvent = static_cast<int>(GeofenceTransitionEvent::GEOFENCE_TRANSITION_EVENT_ENTER) |
        static_cast<int>(GeofenceTransitionEvent::GEOFENCE_TRANSITION_EVENT_EXIT);
    int32_t ret = geofenceInterface->AddGnssGeofence(fenceInfo, monitorEvent);
    LBSLOGD(GNSS, "Successfully AddFence!, %{public}d", ret);
#endif
    if (!SaveFenceWantAgentInfo(request)) {
        return LOCATION_ERRCODE_INVALID_PARAM;
    }
    if (ExecuteFenceProcess(GnssInterfaceCode::ADD_GNSS_GEOFENCE, request)) {
        return ERRCODE_SUCCESS;
    }
    return LOCATION_ERRCODE_NOT_SUPPORTED;
}

LocationErrCode GnssAbility::RemoveFence(std::shared_ptr<GeofenceRequest>& request)
{
    if (!IsSupportGeofence()) {
        LBSLOGI(GNSS, "Is Not Support Geofence");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    if (request == nullptr) {
        LBSLOGE(GNSS, "request is nullptr");
        return ERRCODE_GEOFENCE_FAIL;
    }
    std::vector<std::shared_ptr<GeofenceRequest>> requestList = GetGnssGeofenceRequestList(request);
    if (requestList.empty()) {
        LBSLOGE(GNSS, "bundleName is not registered");
        return ERRCODE_GEOFENCE_INCORRECT_ID;
    }
    LocationErrCode result = ERRCODE_SUCCESS;
    const size_t MAX_SYNC_PROCESS = 30; // 同步处理的最大次数
    size_t i = 0;
    for (; i < requestList.size() && i < MAX_SYNC_PROCESS; ++i) {
        LocationErrCode singleResult = HandleDeleteGnssGeofence(requestList[i]);
        if (singleResult != ERRCODE_SUCCESS) {
            LBSLOGE(GNSS, "Failed to remove fence for request, error: %{public}d", singleResult);
            result = singleResult;
        }
    }
    // 如果还有剩余请求，通过异步消息处理
    if (i < requestList.size()) {
        if (gnssHandler_ != nullptr) {
            AppExecFwk::InnerEvent::Pointer event = AppExecFwk::InnerEvent::Get(
                static_cast<uint32_t>(GnssAbilityInterfaceCode::REMOVE_FENCE), request);
            gnssHandler_->SendEvent(event, REMOVE_FENCE_DELAY_TIME);
        }
    }
    return result;
}

bool GnssAbility::SaveFenceWantAgentInfo(std::shared_ptr<GeofenceRequest> &request)
{
    if (request == nullptr) {
        LBSLOGE(GNSS, "request is invalid");
        return false;
    }
    if (request->GetWantAgent() == nullptr) {
        LBSLOGE(GNSS, "wantAgen is invalid.");
        return false;
    }
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    gnssGeofenceRequestList_.push_back(request);
    gnssGeofenceRequestCountMap_[request->GetBundleName()]++;
    LBSLOGI(GNSS, "After SaveFenceWantAgentInfo size %{public}zu",
        gnssGeofenceRequestList_.size());
    return true;
}

int32_t GnssAbility::GenerateFenceId()
{
    LBSLOGD(GNSS, "GenerateFenceId");
    std::lock_guard<ffrt::mutex> lock(fenceIdMutex_);
    if (fenceId_ > FENCE_MAX_ID) {
        fenceId_ = 0;
    }
    fenceId_++;
    return fenceId_;
}

void GnssAbility::InitGeofenceId(int32_t fenceId)
{
    LBSLOGI(GNSS, "InitGeofenceId fenceId : %{public}d", fenceId);
    fenceId_ = fenceId;
}

LocationErrCode GnssAbility::AddGnssGeofence(std::shared_ptr<GeofenceRequest>& request)
{
    if (!IsSupportGeofence()) {
        LBSLOGI(GNSS, "Is Not Support Geofence");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    if (GetGnssGeofenceRequestMapSize() >= MAX_GNSS_GEOFENCE_REQUEST_NUM) {
        LBSLOGE(GNSS, "Exceeded the limit of the fence request");
        return ERRCODE_GEOFENCE_EXCEED_MAXIMUM;
    }
    if (CheckIfExceedsLimitForOneApp(request->GetBundleName())) {
        LBSLOGE(GNSS, "Exceeded the limit of the fence request for one app");
        DeleteMinExpirationGeofenceRequest(request->GetBundleName());
    }
    int fenceId = 0;
    if (request->GetFenceId() > 0) {
        fenceId = request->GetFenceId();
    } else {
        fenceId = GenerateFenceId();
        request->SetFenceId(fenceId);
    }
#ifdef HDF_DRIVERS_INTERFACE_GEOFENCE_ENABLE
    sptr<IGeofenceInterface> geofenceInterface = IGeofenceInterface::Get();
    if (geofenceInterface == nullptr) {
        LBSLOGE(GNSS, "geofenceInterface is nullptr");
        return ERRCODE_SERVICE_UNAVAILABLE;
    }
    auto geofence = request->GetGeofence();
    GeofenceInfo fenceInfo;
    fenceInfo.fenceIndex = fenceId;
    fenceInfo.latitude = geofence.latitude;
    fenceInfo.longitude = geofence.longitude;
    fenceInfo.radius = geofence.radius;
    auto transitionList = request->GetGeofenceTransitionEventList();
    uint32_t monitorEvent = 0;
    for (size_t i = 0; i < transitionList.size(); i++) {
        GeofenceTransitionEvent status = transitionList[i];
        monitorEvent |= static_cast<uint32_t>(status);
    }
    int32_t ret = geofenceInterface->AddGnssGeofence(fenceInfo, monitorEvent);
    LBSLOGI(GNSS, "Successfully AddGnssGeofence! ret:%{public}d,fenceId:%{public}s",
        ret, std::to_string(fenceId).c_str());
#endif
    RegisterGnssGeofenceCallback(request, request->GetGeofenceTransitionCallback());
    if (ExecuteFenceProcess(GnssInterfaceCode::ADD_GNSS_GEOFENCE, request)) {
        return ERRCODE_SUCCESS;
    }
    return LOCATION_ERRCODE_NOT_SUPPORTED;
}

bool GnssAbility::RegisterGnssGeofenceCallback(std::shared_ptr<GeofenceRequest> &request,
    const sptr<IRemoteObject>& callback)
{
    if (request == nullptr) {
        LBSLOGE(GNSS, "register an invalid request");
        return false;
    }
    if (callback == nullptr) {
        LBSLOGE(GNSS, "register an invalid callback");
        return false;
    }
    auto geofence = request->GetGeofence();
    request->SetRequestExpirationTimeStamp(CommonUtils::GetCurrentTimeMilSec() + geofence.expiration);
    sptr<IRemoteObject::DeathRecipient> death(new (std::nothrow) GnssGeofenceCallbackDeathRecipient());
    callback->AddDeathRecipient(death);
    request->SetTransitionCallbackDeathRecipient(death);
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    gnssGeofenceRequestList_.push_back(request);
    gnssGeofenceRequestCountMap_[request->GetBundleName()]++;
    LBSLOGI(GNSS, "After RegisterGnssGeofenceCallback size %{public}zu",
        gnssGeofenceRequestList_.size());
    return true;
}

LocationErrCode GnssAbility::RemoveGnssGeofence(std::shared_ptr<GeofenceRequest>& request)
{
    if (!IsSupportGeofence()) {
        LBSLOGI(GNSS, "Is Not Support Geofence");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    if (request == nullptr) {
        LBSLOGE(GNSS, "request is nullptr");
        return ERRCODE_SERVICE_UNAVAILABLE;
    }
    if (!IsDuplicateAddRequestForGnssGeofence(request)) {
        LBSLOGE(GNSS, "bundleName is not registered");
        return ERRCODE_GEOFENCE_INCORRECT_ID;
    }
    return HandleDeleteGnssGeofence(request);
}

LocationErrCode GnssAbility::HandleDeleteGnssGeofence(std::shared_ptr<GeofenceRequest>& request)
{
#ifdef HDF_DRIVERS_INTERFACE_GEOFENCE_ENABLE
    sptr<IGeofenceInterface> geofenceInterface = IGeofenceInterface::Get();
    if (geofenceInterface == nullptr) {
        LBSLOGE(GNSS, "geofenceInterface is nullptr");
        return ERRCODE_SERVICE_UNAVAILABLE;
    }
    int32_t ret = geofenceInterface->DeleteGnssGeofence(request->GetFenceId());
    LBSLOGI(GNSS, "Successfully DeleteGnssGeofence! ret:%{public}d,fenceId:%{public}s",
        ret, std::to_string(request->GetFenceId()).c_str());
#endif
    if (ExecuteFenceProcess(GnssInterfaceCode::REMOVE_GNSS_GEOFENCE, request)) {
        return ERRCODE_SUCCESS;
    }
    return LOCATION_ERRCODE_NOT_SUPPORTED;
}

bool GnssAbility::UnregisterGnssGeofenceCallback(int fenceId)
{
    for (auto iter = gnssGeofenceRequestList_.begin(); iter != gnssGeofenceRequestList_.end();) {
        auto gnssGeofenceRequest = *iter;
        if (gnssGeofenceRequest == nullptr) {
            iter++;
            continue;
        }
        if (fenceId == gnssGeofenceRequest->GetFenceId()) {
            if (gnssGeofenceRequest->GetGeofenceTransitionCallback() != nullptr &&
                gnssGeofenceRequest->GetTransitionCallbackRecipient() != nullptr) {
                gnssGeofenceRequest->GetGeofenceTransitionCallback()->RemoveDeathRecipient(
                    gnssGeofenceRequest->GetTransitionCallbackRecipient());
            }
            iter = gnssGeofenceRequestList_.erase(iter);
            ReducedGeoFencesCount(gnssGeofenceRequest->GetBundleName());
            break;
        } else {
            iter++;
        }
    }
    LBSLOGI(GNSS, "After UnregisterGnssGeofenceCallback size:%{public}s",
        std::to_string(gnssGeofenceRequestList_.size()).c_str());
    return true;
}

void GnssAbility::ReportFailedOperationResult(std::shared_ptr<GeofenceRequest> &request, GnssGeofenceOperateType type,
    LocationErrCode code)
{
    sptr<IGnssGeofenceCallback> gnssGeofenceCallback =
                iface_cast<IGnssGeofenceCallback>(request->GetGeofenceTransitionCallback());
    if (gnssGeofenceCallback == nullptr) {
        LBSLOGE(GNSS, "gnssGeofenceCallback is nullptr");
        return;
    }
    gnssGeofenceCallback->OnReportOperationResult(DEFAULT_FENCE_ID,
        static_cast<int>(type), static_cast<int>(DealOperationResult(code)));
}

bool GnssAbility::IsDuplicateAddRequestForGnssGeofence(std::shared_ptr<GeofenceRequest>& request)
{
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    for (auto iter = gnssGeofenceRequestList_.begin();
        iter != gnssGeofenceRequestList_.end(); iter++) {
        auto gnssGeofenceRequest = *iter;
        if (gnssGeofenceRequest == nullptr) {
            continue;
        }
        if (gnssGeofenceRequest->GetBundleName().compare(request->GetBundleName()) == 0 &&
            gnssGeofenceRequest->GetFenceId() == request->GetFenceId()) {
            sptr<IRemoteObject> callback = request->GetGeofenceTransitionCallback();
            if (callback != nullptr) {
                gnssGeofenceRequest->SetGeofenceTransitionCallback(callback);
                sptr<IRemoteObject::DeathRecipient> death(new (std::nothrow) GnssGeofenceCallbackDeathRecipient());
                callback->AddDeathRecipient(death);
                gnssGeofenceRequest->SetTransitionCallbackDeathRecipient(death);
                gnssGeofenceRequest->SetPid(request->GetPid());
                gnssGeofenceRequest->SetTokenId(request->GetTokenId());
                gnssGeofenceRequest->SetTokenIdEx(request->GetTokenIdEx());
                gnssGeofenceRequest->SetFirstTokenId(request->GetFirstTokenId());
            }
            return true;
        }
    }
    return false;
}

bool GnssAbility::IsDuplicateOnRequestForGnssGeofence(std::shared_ptr<GeofenceRequest>& request)
{
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    for (auto iter = gnssGeofenceRequestList_.begin();
        iter != gnssGeofenceRequestList_.end(); iter++) {
        auto gnssGeofenceRequest = *iter;
        if (gnssGeofenceRequest == nullptr) {
            continue;
        }
        auto wantAgentPtr = gnssGeofenceRequest->GetWantAgent();
        if (AbilityRuntime::WantAgent::WantAgentHelper::IsEquals(wantAgentPtr, request->GetWantAgent()) == 0 &&
            gnssGeofenceRequest->GetBundleName().compare(request->GetBundleName()) == 0 &&
            IsSameGeofence(gnssGeofenceRequest->GetGeofence(), request->GetGeofence())) {
            return true;
        }
    }
    return false;
}

std::vector<std::shared_ptr<GeofenceRequest>> GnssAbility::GetGnssGeofenceRequestList(
    std::shared_ptr<GeofenceRequest>& request)
{
    std::vector<std::shared_ptr<GeofenceRequest>> matchedRequests;
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);

    for (auto iter = gnssGeofenceRequestList_.begin(); iter != gnssGeofenceRequestList_.end(); iter++) {
        auto gnssGeofenceRequest = *iter;
        if (gnssGeofenceRequest == nullptr) {
            continue;
        }
        auto wantAgentPtr = gnssGeofenceRequest->GetWantAgent();
        if (AbilityRuntime::WantAgent::WantAgentHelper::IsEquals(wantAgentPtr, request->GetWantAgent()) != 0 ||
            gnssGeofenceRequest->GetBundleName().compare(request->GetBundleName()) != 0 ||
            !IsSameGeofence(gnssGeofenceRequest->GetGeofence(), request->GetGeofence())) {
            continue;
        }
        auto matchedRequest = std::make_shared<GeofenceRequest>(*request);
        matchedRequest->SetFenceId(gnssGeofenceRequest->GetFenceId());
        matchedRequests.push_back(matchedRequest);
    }

    return matchedRequests;
}

bool GnssAbility::IsSameGeofence(const GeoFence& geoFence, const GeoFence& requestGeoFence)
{
    return (geoFence.latitude == requestGeoFence.latitude) &&
           (geoFence.longitude == requestGeoFence.longitude) &&
           (geoFence.radius == requestGeoFence.radius) &&
           (geoFence.expiration == requestGeoFence.expiration) &&
           (geoFence.coordinateSystemType == requestGeoFence.coordinateSystemType);
}

bool GnssAbility::IsProcessRunning(pid_t pid, const uint32_t tokenId)
{
    return AppBackgroundStatusManager::GetInstance()->IsProcessRunning(pid, tokenId, false);
}

bool GnssAbility::RemoveGnssGeofenceByCallbackWhenAppDie(sptr<IRemoteObject> callbackObj)
{
    if (callbackObj == nullptr) {
        return false;
    }
    std::vector<std::shared_ptr<GeofenceRequest>> requestList;
    {
        std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
        for (auto iter = gnssGeofenceRequestList_.begin(); iter != gnssGeofenceRequestList_.end();) {
            auto gnssGeofenceRequest = *iter;
            if (gnssGeofenceRequest == nullptr) {
                iter++;
                continue;
            }
            sptr<IRemoteObject> reuestCallback = gnssGeofenceRequest->GetGeofenceTransitionCallback();
            if (reuestCallback != nullptr && reuestCallback == callbackObj &&
                gnssGeofenceRequest->GetTransitionCallbackRecipient() != nullptr) {
                gnssGeofenceRequest->GetGeofenceTransitionCallback()->RemoveDeathRecipient(
                    gnssGeofenceRequest->GetTransitionCallbackRecipient());
#ifdef NOTIFICATION_ENABLE
                auto notificationRequestList = gnssGeofenceRequest->GetNotificationRequestList();
                if (notificationRequestList.size() == 0 &&
                    gnssGeofenceRequest->GetFenceExtensionAbilityName().empty()) {
                    requestList.push_back(gnssGeofenceRequest);
                }
#endif
                break;
            } else {
                iter++;
            }
        }
    }
    for (auto& request : requestList) {
        if (gnssHandler_ != nullptr) {
            AppExecFwk::InnerEvent::Pointer event = AppExecFwk::InnerEvent::Get(
                static_cast<uint32_t>(GnssAbilityInterfaceCode::REMOVE_GEOFENCE), request);
            gnssHandler_->SendEvent(event);
        }
    }
    LBSLOGD(GNSS, "After RemoveGnssGeofenceByCallbackWhenAppDie size:%{public}s",
        std::to_string(gnssGeofenceRequestList_.size()).c_str());
    return true;
}

size_t GnssAbility::GetGnssGeofenceRequestMapSize()
{
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    return gnssGeofenceRequestList_.size();
}

bool GnssAbility::CheckIfExceedsLimitForOneApp(const std::string& bundleName)
{
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    auto it = gnssGeofenceRequestCountMap_.find(bundleName);
    if (it != gnssGeofenceRequestCountMap_.end()) {
        return it->second >= MAX_GNSS_GEOFENCE_REQUEST_NUM_FOR_ONE_APP;
    }
    return false;
}

void GnssAbility::ReducedGeoFencesCount(const std::string& bundleName)
{
    auto it = gnssGeofenceRequestCountMap_.find(bundleName);
    if (it != gnssGeofenceRequestCountMap_.end()) {
        if (it->second > 0) {
            it->second--;
        }
        if (it->second == 0) {
            gnssGeofenceRequestCountMap_.erase(it);
        }
    }
}

#ifdef HDF_DRIVERS_INTERFACE_GEOFENCE_ENABLE
void GnssAbility::ReportGeofenceOperationResult(
    int fenceId, GeofenceOperateType type, GeofenceOperateResult result)
{
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    auto geofenceRequest = GetGeofenceRequestByFenceId(fenceId);
    if (geofenceRequest == nullptr) {
        LBSLOGE(GNSS, "request is nullptr");
        return;
    }
    if (type == GeofenceOperateType::TYPE_DELETE && result == GeofenceOperateResult::GEOFENCE_OPERATION_SUCCESS) {
        UnregisterGnssGeofenceCallback(fenceId);
    }
    bool needSaveToFile = false;
#ifdef NOTIFICATION_ENABLE
    if (geofenceRequest->GetNotificationRequestList().size() != 0) {
        needSaveToFile = true;
    }
#endif
    if (geofenceRequest->GetWantAgent() != nullptr) {
        needSaveToFile = true;
    }
    if (!geofenceRequest->GetFenceExtensionAbilityName().empty()) {
        needSaveToFile = true;
    }
    if (needSaveToFile) {
        SaveGeoFenceRequestToFile();
    }
    auto callback = geofenceRequest->GetGeofenceTransitionCallback();
    if (callback == nullptr) {
        LBSLOGE(GNSS, "callback is nullptr");
        return;
    }
    bool appAliveStatus = IsProcessRunning(geofenceRequest->GetPid(), geofenceRequest->GetTokenId());
    if (!appAliveStatus) {
        LBSLOGE(GNSS, "app alive status is false");
        return;
    }
    sptr<IGnssGeofenceCallback> gnssGeofenceCallback = iface_cast<IGnssGeofenceCallback>(callback);
    gnssGeofenceCallback->OnReportOperationResult(
        fenceId, static_cast<int>(type), static_cast<int>(result));
}

std::vector<std::shared_ptr<GeofenceRequest>> GnssAbility::ReadGeoFenceRequestFromFile()
{
    std::vector<std::shared_ptr<GeofenceRequest>> requestList;
    // 读取文件内容
    std::string fileContent = ReadFileContent();
    // 验证 JSON 字符串是否有效
    if (fileContent.empty() || !nlohmann::json::accept(fileContent)) {
        return requestList;
    }
    auto *geofenceRequestRoot = cJSON_Parse(fileContent.c_str());
    if (geofenceRequestRoot == nullptr) {
        return requestList;
    }
    cJSON *item = NULL;
    cJSON_ArrayForEach(item, geofenceRequestRoot) {
        const char *key = item->string;
        cJSON *value = cJSON_GetObjectItemCaseSensitive(geofenceRequestRoot, key);
        if (!cJSON_IsString(value)) {
            cJSON_Delete(geofenceRequestRoot);
            return requestList;
        }
        std::string geofenceRequestStr = item->valuestring;
        // 第三个参数 false 表示不抛出异常
        nlohmann::json jsonObj = nlohmann::json::parse(geofenceRequestStr, nullptr, false);
        // 检查解析是否成功
        if (jsonObj.is_discarded()) {
            cJSON_Delete(geofenceRequestRoot);
            return requestList;
        }
        std::shared_ptr<GeofenceRequest> request = GeofenceRequest::FromJson(jsonObj);
        if (request != nullptr) {
            requestList.push_back(request);
        }
    }
    cJSON_Delete(geofenceRequestRoot);
    return requestList;
}

std::string GnssAbility::ReadFileContent()
{
    if (!CommonUtils::IsExistFile(GEOFENCE_REQUEST_FILE_PATH)) {
        return "";
    }
    std::ifstream fs(GEOFENCE_REQUEST_FILE_PATH);
    if (!fs.is_open()) {
        LBSLOGE(GNSS, "fs.is_open false, return");
        return "";
    }
    std::string line;
    std::string content;
    std::getline(fs, line);
    while (std::getline(fs, content)) {
        line += content;
    }
    fs.clear();
    fs.close();
    return line;
}

void GnssAbility::SaveGeoFenceRequestToFile()
{
    if (!CommonUtils::IsExistFile(GEOFENCE_REQUEST_FILE_PATH)) {
        CommonUtils::CreateFile(GEOFENCE_REQUEST_FILE_PATH, "0");
    }
    std::ofstream fs(GEOFENCE_REQUEST_FILE_PATH, std::ofstream::out | std::ofstream::trunc);
    if (!fs || !fs.is_open()) {
        LBSLOGE(GNSS, "fs.is_open false, return");
        return;
    }
    cJSON *root = cJSON_CreateObject();
    for (auto gnssGeofenceRequest : gnssGeofenceRequestList_) {
        nlohmann::json jsonObject;
        gnssGeofenceRequest->ToJson(jsonObject);
        std::string geoFenceRequestStr = jsonObject.dump();
        cJSON_AddItemToObject(root, std::to_string(gnssGeofenceRequest->GetFenceId()).c_str(),
            cJSON_CreateString(geoFenceRequestStr.c_str()));
    }
    auto jsonString = cJSON_Print(root);
    if (jsonString != nullptr) {
        fs.write(jsonString, strlen(jsonString));
        cJSON_free(jsonString);
    }
    cJSON_Delete(root);
    fs.clear();
    fs.close();
    return;
}
