#ifdef HDF_DRIVERS_INTERFACE_GEOFENCE_ENABLE
void GnssAbility::ReportGeofenceEvent(int fenceIndex, GeofenceEvent event)
{
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    auto request = GetGeofenceRequestByFenceId(fenceIndex);
    if (request == nullptr) {
        LBSLOGE(GNSS, "request is nullptr");
        return;
    }
    if (CommonUtils::GetCurrentTimeMilSec() > request->GetRequestExpirationTimeStamp()) {
        LBSLOGE(GNSS, "request is expiration");
        if (gnssHandler_ != nullptr) {
            AppExecFwk::InnerEvent::Pointer event = AppExecFwk::InnerEvent::Get(
                static_cast<uint32_t>(GnssAbilityInterfaceCode::REMOVE_GEOFENCE), request);
            gnssHandler_->SendEvent(event);
        }
        return;
    }
    if (NotifyGnssfenceStatusByWantAgent(request, event)) {
        return;
    }
    NotifyGnssfenceStatusByNotification(request, event);
    uint32_t tokenId = request->GetTokenId();
    if (request->IsTokenIdValid() &&
        !PermissionManager::CheckLocationPermission(tokenId, request->GetFirstTokenId())) {
        LBSLOGE(GNSS,
            "ReportGeofenceEvent CheckLocationPermission false, tokenId = %{public}d", tokenId);
        return;
    }
    if (request->IsTokenIdValid() &&
        IsAppBackground(request->GetBundleName(), tokenId, request->GetTokenIdEx(), request->GetUid(),
        request->GetPid()) && !PermissionManager::CheckBackgroundPermission(tokenId, request->GetFirstTokenId())) {
        LBSLOGE(GNSS,
            "ReportGeofenceEvent CheckBackgroundPermission false, tokenId = %{public}d", tokenId);
        return;
    }
    NotifyGnssfenceStatusByFenceExtension(request, event);
    NotifyGnssfenceStatusByCallback(request, event);
}

bool GnssAbility::NotifyGnssfenceStatusByWantAgent(const std::shared_ptr<GeofenceRequest> &request, GeofenceEvent event)
{
    if (request == nullptr) {
        LBSLOGE(GNSS, "NotifyGnssfenceStatusByWantAgent request is nullptr");
        return false;
    }
    auto wantAgent = request->GetWantAgent();
    if (wantAgent == nullptr) {
        LBSLOGI(GNSS, "%{public}s: wantAgent == nullptr", __func__);
        return false;
    }
    uint32_t tokenId = request->GetTokenId();
    if (request->IsTokenIdValid() &&
        !PermissionManager::CheckApproximatelyPermission(tokenId, request->GetFirstTokenId())) {
        LBSLOGE(GNSS,
            "NotifyGnssfenceStatusByWantAgent CheckApproximatelyPermission false, tokenId = %{public}d", tokenId);
        return false;
    }
    std::shared_ptr<AAFwk::Want> want = OHOS::AbilityRuntime::WantAgent::WantAgentHelper::GetWant(wantAgent);
    if (!want) {
        LBSLOGE(GNSS, "%{public}s: nullptr want.", __func__);
        return false;
    }
    want->SetParam("transition", static_cast<GeofenceTransitionEvent>(event));
    LBSLOGI(GNSS, "%{public}s: want: %{public}s", __func__, want->ToString().c_str());
    AbilityRuntime::WantAgent::TriggerInfo triggerInfo("", nullptr, want, WANT_CODE_ELEVEN);
    sptr<AbilityRuntime::WantAgent::CompletedDispatcher> data;
    AbilityRuntime::WantAgent::WantAgentHelper::TriggerWantAgent(wantAgent, nullptr, triggerInfo, data, nullptr);
    return true;
}

void GnssAbility::NotifyGnssfenceStatusByNotification(
    const std::shared_ptr<GeofenceRequest> &request, GeofenceEvent event)
{
    if (request == nullptr) {
        LBSLOGE(GNSS, "NotifyGnssfenceStatusByNotification request is nullptr");
        return;
    }
    auto transitionStatusList = request->GetGeofenceTransitionEventList();
#ifdef NOTIFICATION_ENABLE
        auto notificationRequestList = request->GetNotificationRequestList();
        if (transitionStatusList.size() != notificationRequestList.size()) {
            LBSLOGE(GNSS, "transitionStatusList size does not equals to notificationRequestList size");
            return;
        }
    for (size_t i = 0; i < transitionStatusList.size(); i++) {
        if (transitionStatusList[i] !=
            static_cast<GeofenceTransitionEvent>(event)) {
            continue;
        }
        auto notificationRequest = notificationRequestList[i];
        if (notificationRequest != nullptr) {
            notificationRequest->SetCreatorUid(request->GetUid());
            int ret = Notification::NotificationHelper::PublishNotification(*notificationRequest);
            if (ret != ERR_OK) {
                LBSLOGE(GNSS, "PublishNotification faild ret :%{public}d", ret);
            }
        }
    }
#endif
}

void GnssAbility::NotifyGnssfenceStatusByFenceExtension(
    const std::shared_ptr<GeofenceRequest> &request, GeofenceEvent event)
{
    if (request == nullptr) {
        LBSLOGE(GNSS, "NotifyGnssfenceStatusByFenceExtension request is nullptr");
        return;
    }
    if (request->GetFenceExtensionAbilityName().empty()) {
        return;
    }
    FenceStruct fenceStruct;
    fenceStruct.request = request;
    fenceStruct.transitionEvent = static_cast<int>(event);
    HookUtils::ExecuteHook(
        LocationProcessStage::NOTIFY_GEOFENCE_STATUS_BY_FENCEEXTENSION_PROCESS, (void *)&fenceStruct, nullptr);
}

void GnssAbility::NotifyGnssfenceStatusByCallback(const std::shared_ptr<GeofenceRequest> &request, GeofenceEvent event)
{
    auto callback = request->GetGeofenceTransitionCallback();
    if (callback == nullptr) {
        LBSLOGE(GNSS, "callback is nullptr");
        return;
    }
    sptr<IGnssGeofenceCallback> gnssGeofenceCallback = iface_cast<IGnssGeofenceCallback>(callback);
    auto transitionStatusList = request->GetGeofenceTransitionEventList();
    bool appAliveStatus = IsProcessRunning(request->GetPid(), request->GetTokenId());
    for (size_t i = 0; i < transitionStatusList.size(); i++) {
        if (transitionStatusList[i] !=
            static_cast<GeofenceTransitionEvent>(event)) {
            continue;
        }
        if (appAliveStatus) {
            GeofenceTransition geofenceTransition;
            geofenceTransition.fenceId = request->GetFenceId();
            geofenceTransition.event = transitionStatusList[i];
            gnssGeofenceCallback->OnTransitionStatusChange(geofenceTransition);
            break;
        }
    }
}

bool GnssAbility::IsAppBackground(std::string bundleName, uint32_t tokenId, uint64_t tokenIdEx, pid_t uid, pid_t pid)
{
    auto backgroundManager = AppBackgroundStatusManager::GetInstance();
    if (!backgroundManager->IsAppBackground(uid, bundleName)) {
        return false;
    }
    if (!HookUtils::ExecuteHookWhenCheckIsAppBackground(bundleName)) {
        return false;
    }
    if (backgroundManager->IsAppHasFormVisible(tokenId, tokenIdEx)) {
        return false;
    }
    if (backgroundManager->IsAppInLocationContinuousTasks(uid, pid)) {
        return false;
    }
    return true;
}
