        return;
    }
    if (gnssBatchingWorkingStatus_.load() == GNSS_BATCHING_WORKING_STATUS_SESSION_END) {
        LBSLOGD(GNSS, "GNSS batching stopped");
        return;
    }
    int ret = gnssInterface->StopGnss(GNSS_START_TYPE_GNSS_CACHE);
