        gnssBatchingWorkingStatus_.store(GNSS_BATCHING_WORKING_STATUS_SESSION_END);
        WriteLocationInnerEvent(STOP_GNSS_CACHE, {});
    } else {
        WriteLocationInnerEvent(HDI_EVENT,
