LocationErrCode GnssAbility::QuerySupportCoordinateSystemType(
    std::vector<CoordinateSystemType>& coordinateSystemTypes)
{
    std::vector<CoordinateSystemType> supportedTypes;
    supportedTypes.push_back(CoordinateSystemType::WGS84);
    FenceStruct fenceStruct;
    fenceStruct.requestCode =
        static_cast<int>(GnssInterfaceCode::GET_GEOFENCE_SUPPORT_COORDINATE_SYSTEM_TYPE);
    fenceStruct.coordinateSystemTypes = supportedTypes;
    HookUtils::ExecuteHook(
        LocationProcessStage::FENCE_REQUEST_PROCESS, (void *)&fenceStruct, nullptr);
    coordinateSystemTypes = fenceStruct.coordinateSystemTypes;

    return ERRCODE_SUCCESS;
}

LocationErrCode GnssAbility::GetActiveGeoFences(std::string bundleName,
    std::map<int, std::shared_ptr<Geofence>>& fenceMap)
{
    if (!IsSupportGeofence()) {
        LBSLOGI(GNSS, "Is Not Support Geofence");
        return LOCATION_ERRCODE_NOT_SUPPORTED;
    }
    std::unique_lock<ffrt::mutex> lock(gnssGeofenceRequestListMutex_);
    for (auto iter = gnssGeofenceRequestList_.begin(); iter != gnssGeofenceRequestList_.end(); iter++) {
        auto request = *iter;
        if (request == nullptr) {
            continue;
        }
        if (request->GetBundleName() == bundleName) {
            std::shared_ptr<Geofence> geofence = std::make_shared<Geofence>();
            geofence->SetLatitude(request->GetGeofence().latitude);
            geofence->SetLongitude(request->GetGeofence().longitude);
            geofence->SetRadius(request->GetGeofence().radius);
            geofence->SetExpiration(request->GetGeofence().expiration);
            geofence->SetCoordinateSystemType(request->GetGeofence().coordinateSystemType);
            fenceMap.insert(std::make_pair(request->GetFenceId(), geofence));
        }
    }
    LBSLOGI(GNSS, "map size = %{public}zu", fenceMap.size());
    return ERRCODE_SUCCESS;
}

